/**
 * Represents a single interview question generated by the AI.
 */
export interface Question {
  /** Optional category for the question (e.g., "Behavioral", "Situational"). */
  category?: string;
  /** The actual text of the interview question. */
  question: string;
  /** A concise explanation of what the interviewer learns from this question. */
  why_it_matters?: string;
}

/**
 * Defines the expected structured JSON response from the backend API.
 */
export interface GenerateQuestionsResponse {
  /** Array of generated questions. */
  questions: Question[];
}

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL;

/**
 * Fires a silent GET /health to wake the backend (Render free tier cold start).
 * Called on app mount so the backend warms while the user fills the form.
 */
export function warmupBackend(): void {
  if (!API_BASE_URL) return;
  fetch(`${API_BASE_URL}/health`).catch(() => {});
}

/**
 * Calls the backend API to generate interview questions for a specific job title.
 *
 * @param jobTitle - The job title for which to generate questions.
 * @returns A promise resolving to an array of generated Question objects.
 * @throws Will throw an error if the network request fails or returns a non-ok status.
 */
export async function generateQuestions(jobTitle: string): Promise<Question[]> {
  if (!API_BASE_URL) {
    throw new Error("VITE_API_BASE_URL is not defined. Please check your environment variables.");
  }

  // Execute a POST request to the backend endpoint.
  const response = await fetch(`${API_BASE_URL}/questions`, {
    method: 'POST',
    headers: {
      // Indicate that we are sending JSON data.
      'Content-Type': 'application/json',
    },
    // Serialize the payload to JSON.
    body: JSON.stringify({ job_title: jobTitle }),
  });

  // Check if the response indicates success (status 200-299).
  if (!response.ok) {
    throw new Error('Failed to generate questions. Please try again later.');
  }

  // Parse the structured JSON response returned by the backend.
  const data: GenerateQuestionsResponse = await response.json();
  
  // Guard against malformed backend responses to prevent frontend crashes (.map is not a function).
  if (!data || !Array.isArray(data.questions)) {
    throw new Error('Received an invalid response format from the server.');
  }
  
  // Return the extracted array of questions.
  return data.questions;
}
